input.sparql:
SELECT ?chiller ?point ?ts WHERE {
  ?ref ref:hasTimeseriesId ?ts .
  ?point ref:hasExternalReference ?ref .
  FILTER(str(?point) LIKE "%Chiller01%")
  ?point brick:hasProperty ?prop .
}

SELECT ?point ?ts WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  FILTER(str(?point) LIKE "%Chiller01%")
}

SELECT ?point ?ts ?class WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  ?point a ?class .
  FILTER(CONTAINS(STR(?point), "Chiller"))
}
